}

query TestTwoPagesQuery(
  $id: ID!
) {
  character(id: $id) {
    id
    notes(first: 2) {
      edges {
        node {
          id
          text
          __typename
        }
        cursor
      }
      pageInfo {
        endCursor
        hasNextPage
      }
    }
  }
  node(id: $id) {
    __typename
    ... on Character {
      notes(first: 2, after: "c2") {
        edges {
          node {
            id
            text
            __typename
          }
          cursor
        }
        pageInfo {
          endCursor
          hasNextPage
        }
      }
    }
    id
  }
}
